package kik.qa;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.Callable;import java.util.function.BooleanSupplier;import org.json.*;import kik.i18n.*;

/** Tests real create/skip/save/revisit flows without changing the original profile's data. */
public final class OnboardingAudit extends Instrumentation {
 Context c;String original,originalList;volatile Activity current;List<String> qa=new ArrayList<>();List<Activity> activities=new ArrayList<>();JSONArray checks=new JSONArray();boolean passed=true;File dir;Map<String,String> originalFiles=new HashMap<>();
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 Object get(Object o,String n){try{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}catch(Exception e){throw new RuntimeException(e);}}
 Object call(String type,String name,Class<?>[] sig,Object...args){try{Method m=Class.forName(type).getDeclaredMethod(name,sig);m.setAccessible(true);return m.invoke(null,args);}catch(Exception e){throw new RuntimeException(e);}}
 <T>T ui(Callable<T> f){Object[] r=new Object[2];runOnMainSync(()->{try{r[0]=f.call();}catch(Throwable e){r[1]=e;}});if(r[1]!=null)throw new RuntimeException((Throwable)r[1]);return (T)r[0];}
 boolean await(BooleanSupplier f,long ms){long end=SystemClock.elapsedRealtime()+ms;while(SystemClock.elapsedRealtime()<end){try{if(f.getAsBoolean())return true;}catch(Throwable ignored){}SystemClock.sleep(80);}return false;}
 void check(String label,boolean ok)throws Exception{checks.put(new JSONObject().put("name",label).put("passed",ok));Bundle b=new Bundle();b.putString("stream",(ok?"PASS ":"FAIL ")+label+"\n");sendStatus(0,b);if(!ok)throw new AssertionError(label);}
 List<View> views(View v){List<View> out=new ArrayList<>();out.add(v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)out.addAll(views(((ViewGroup)v).getChildAt(i)));return out;}
 View text(Activity a,String wanted){return ui(()->{for(View v:views(a.getWindow().getDecorView()))if(v instanceof TextView&&wanted.contentEquals(((TextView)v).getText()))return v;return null;});}
 void click(View v){ui(()->{v.performClick();return null;});}
 Activity profiles(){if(current==null)return startActivitySync(new Intent(c,ProfilesActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Activity before=current;ui(()->{before.startActivity(new Intent(before,ProfilesActivity.class));return null;});if(!await(()->current instanceof ProfilesActivity&&current!=before,10000))throw new AssertionError("Profiles did not open");return current;}
 TasteActivity taste(){if(!await(()->current instanceof TasteActivity&&ui(()->current.getWindow().getDecorView().hasWindowFocus()),10000))throw new AssertionError("Taste activity not shown");return (TasteActivity)current;}
 HomeActivity home(){if(!await(()->current instanceof HomeActivity,10000))throw new AssertionError("Home not shown");HomeActivity h=(HomeActivity)current;if(!await(()->ui(()->(Boolean)get(h,"loadedOnce")),30000))throw new AssertionError("Home did not load");return h;}
 String createUI(String suffix)throws Exception{Activity p=profiles();View add=text(p,"+ Додати профіль");check("profile creation action available",add!=null);click(add);String name="QA "+suffix+" "+System.currentTimeMillis()%100000;ui(()->{List<EditText> inputs=new ArrayList<>();for(View v:views(p.getWindow().getDecorView()))if(v instanceof EditText)inputs.add((EditText)v);inputs.get(0).setText(name);inputs.get(1).setText("Audit1234");return null;});click(text(p,"Створити"));TasteActivity t=taste();String id=ProfileStore.current(c);qa.add(id);check("new profile opens initial taste selection",ProfileStore.nameOf(c,id).equals(name)&&ProfileStore.needsTasteSetup(c,id)&&(Boolean)get(t,"setup"));return id;}
 Map<String,Object> choices(TasteActivity t){return (Map<String,Object>)get(t,"choices");}
 Set<String> selected(TasteActivity t){return (Set<String>)get(t,"selected");}
 Map<String,FrameLayout> frames(TasteActivity t){return (Map<String,FrameLayout>)get(t,"frames");}
 List<String> pickThree(TasteActivity t)throws Exception{check("starter catalogue has films and series",await(()->ui(()->{boolean films=false,series=false;for(Object i:choices(t).values()){String link=(String)get(i,"link");films|=link.contains("/films/");series|=link.contains("/series/");}return films&&series&&choices(t).size()>=3;}),20000));List<String> keys=ui(()->new ArrayList<>(choices(t).keySet()).subList(0,3));for(String key:keys)click(ui(()->frames(t).get(key)));check("three titles can be selected",ui(()->selected(t).size()==3));return new ArrayList<>(keys);}
 List<?> ratings(String p){return (List<?>)call("kik.i18n.RatingStore","list",new Class[]{Context.class,String.class},c,p);}
 void shot(String name)throws Exception{SystemClock.sleep(400);try(FileOutputStream out=new FileOutputStream(new File(dir,name+".png"))){getUiAutomation().takeScreenshot().compress(Bitmap.CompressFormat.PNG,100,out);}}
 void bounds(View v,String label)throws Exception{ui(()->{v.requestFocus();return null;});SystemClock.sleep(250);boolean visible=ui(()->{Rect shown=new Rect();Matrix m=new Matrix();v.transformMatrixToGlobal(m);RectF full=new RectF(0,0,v.getWidth(),v.getHeight());m.mapRect(full);return v.getGlobalVisibleRect(shown)&&full.left>=shown.left-2&&full.top>=shown.top-2&&full.right<=shown.right+2&&full.bottom<=shown.bottom+2;});check(label,visible);}
 String content(File f)throws Exception{if(!f.exists())return "missing";try(FileInputStream in=new FileInputStream(f);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,0,n);return android.util.Base64.encodeToString(out.toByteArray(),2);}}
 void checkSignals(String p)throws Exception{Object snapshot=call("kik.i18n.Recommendations","snapshot",new Class[]{Context.class,String.class},c,p);List<?> signals=(List<?>)get(snapshot,"signals");check("selected titles become strong recommendation signals",signals.size()==3&&signals.stream().allMatch(s->((Double)get(s,"weight"))==6d));}
 void tests()throws Exception{
  check("existing profile is not forced through setup",!ProfileStore.needsTasteSetup(c,original));String a=createUI("Skip");TasteActivity t=taste();check("skip is available immediately",ui(()->((Button)get(t,"skip")).isEnabled()));check("continue is disabled with no selection",ui(()->!((Button)get(t,"save")).isEnabled()));List<String> keys=pickThree(t);check("draft has not created ratings",ratings(a).isEmpty());bounds((View)get(t,"skip"),"skip button fits when focused");bounds((View)get(t,"save"),"continue button fits when focused");bounds(frames(t).get(keys.get(0)),"selected poster fits when focused");shot("onboarding-selected");
  ui(()->{t.recreate();return null;});check("draft survives activity recreation",await(()->current instanceof TasteActivity&&current!=t&&ui(()->selected((TasteActivity)current).containsAll(keys)),10000));TasteActivity recreated=(TasteActivity)current;check("recreated selection still has no persisted ratings",ratings(a).isEmpty());
  check("cards become available after recreation",await(()->ui(()->frames(recreated).size()>=3),10000));waitForIdleSync();ui(()->{frames(recreated).get(keys.get(0)).requestFocus();return null;});check("poster obtains remote focus",await(()->ui(()->frames(recreated).get(keys.get(0)).hasFocus()),3000));sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_RIGHT);check("D-pad moves between posters",await(()->ui(()->recreated.getCurrentFocus()==frames(recreated).get(keys.get(1))),3000));View next=ui(()->recreated.getCurrentFocus());boolean was=ui(()->next.isSelected());sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_CENTER);check("remote OK toggles selection",ui(()->next.isSelected()!=was));sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_CENTER);
  click((View)get(recreated,"skip"));HomeActivity h=home();check("skip completes setup without saving draft",!ProfileStore.needsTasteSetup(c,a)&&ratings(a).isEmpty());
  View customize=text(h,"Налаштувати смак");check("taste can be opened later",customize!=null);click(customize);TasteActivity edit=taste();check("later editor is not forced onboarding",!(Boolean)get(edit,"setup"));pickThree(edit);click((View)get(edit,"save"));home();check("later selection is saved for this profile",ratings(a).size()==3);checkSignals(a);
  String b=createUI("Save");TasteActivity initial=taste();check("new profile cannot inherit earlier likes",ratings(b).isEmpty()&&ui(()->selected(initial).isEmpty()));pickThree(initial);click((View)get(initial,"save"));home();check("continue saves choices and completes setup",ratings(b).size()==3&&!ProfileStore.needsTasteSetup(c,b));checkSignals(b);check("other profile keeps its own selection",ratings(a).size()==3);
  Activity p=profiles();ui(()->{ProfileStore.choose(p,a);return null;});HomeActivity again=home();check("completed profile opens home without repeating setup",a.equals(ProfileStore.current(c))&&!(current instanceof TasteActivity));click(text(again,"Налаштувати смак"));TasteActivity later=taste();check("saved choices are checked on revisit",await(()->ui(()->selected(later).size()==3&&frames(later).size()>=3),10000));String key=ui(()->selected(later).iterator().next());click(ui(()->frames(later).get(key)));check("editor supports deselection",ui(()->selected(later).size()==2));sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);home();check("cancel discards changes to existing taste",ratings(a).size()==3);
  createUI("Back");TasteActivity back=taste();String backId=ProfileStore.current(c);sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);home();check("back safely skips initial setup",!ProfileStore.needsTasteSetup(c,backId)&&ratings(backId).isEmpty());
  String d=createUI("Isolation");TasteActivity stale=taste();pickThree(stale);c.getSharedPreferences("kik_profiles",0).edit().putString("current",b).commit();click((View)get(stale,"save"));SystemClock.sleep(400);check("stale screen cannot save into another profile",ratings(d).isEmpty()&&ratings(b).size()==3&&ProfileStore.needsTasteSetup(c,d));ui(()->{stale.finish();return null;});
 }
 @Override public void onStart(){c=getTargetContext();original=ProfileStore.current(c);originalList=c.getSharedPreferences("kik_profiles",0).getString("list","[]");dir=new File(c.getExternalFilesDir(null),"design-audit");dir.mkdirs();
 ((Application)c.getApplicationContext()).registerActivityLifecycleCallbacks(new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){activities.add(a);}public void onActivityResumed(Activity a){current=a;}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}});
 try{for(String prefix:new String[]{"kik_progress_","kik_later_","kik_taste_"})originalFiles.put(prefix,content(new File(c.getFilesDir(),prefix+original+".json")));ProfileStore.picked=true;tests();}
 catch(Throwable t){passed=false;android.util.Log.e("KIK.OnboardingAudit","Failed",t);try{checks.put(new JSONObject().put("error",t.toString()).put("passed",false));}catch(Exception ignored){}}
 finally{try{ui(()->{for(Activity a:new ArrayList<>(activities))if(!a.isDestroyed())a.finish();return null;});c.getSharedPreferences("kik_profiles",0).edit().putString("current",original).commit();for(String q:qa)ProfileStore.delete(c,q);c.getSharedPreferences("kik_profiles",0).edit().putString("list",originalList).putString("current",original).commit();for(String prefix:originalFiles.keySet())check("original profile unchanged: "+prefix,originalFiles.get(prefix).equals(content(new File(c.getFilesDir(),prefix+original+".json"))));check("all temporary profiles deleted",ProfileStore.list(c).stream().noneMatch(p->qa.contains(p.id)));}catch(Throwable t){passed=false;}
 try{try(FileOutputStream out=new FileOutputStream(new File(dir,"onboarding.json"))){out.write(new JSONObject().put("passed",passed).put("checks",checks).toString(2).getBytes("UTF-8"));}}catch(Exception e){passed=false;}Bundle b=new Bundle();b.putString("stream","Onboarding audit passed="+passed+" checks="+checks.length());finish(passed?-1:0,b);}}
}
